final _cache = <String, List<County>>{};

/// 그 주의 카운티 (이름순). 없으면 빈 목록.
List<County> countiesOf(String? state) {
  if (state == null) return const [];
  return _cache.putIfAbsent(state, () {
    final raw = _data[state];
    if (raw == null) return const [];
    return [
      for (final p in raw.split(';'))
        if (p.isNotEmpty)
          (() {
            final f = p.split('|');
            return County(f[0], double.parse(f[1]), f[2] == '1');
          })(),
    ];
  });
}

County? countyOf(String? state, String? name) {
  for (final c in countiesOf(state)) {
    if (c.name == name) return c;
  }
  return null;
}
